"""Hidden symmetry test: the group generated by invertible circulant maps x -> c * x (units of F2[X]/(X^12 - 1))
and the multipliers x_i -> x_{k i} (k = 5, 7, 11).  Every such map commutes with the rotation (up to the
multiplier automorphism), is linear and invertible, so it preserves RS, degree and bentness.
For each bent polar: image polars of several functions of its phase space under a set of generators; the images
must not depend on the chosen function; orbits = connected components.
Usage: python simetria_circulante.py <bent polars file> [--out file.json]"""
import os, sys, json, random
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np

XS = np.arange(4096)
PAIRS6 = [(i, j) for i in range(6) for j in range(i + 1, 6)]
Z = np.arange(64)[:, None]; Wd = np.arange(64)[None, :]
XOF = ((Z ^ Wd) | (Wd << 6))                                      # x index of (z, w)


def circ_matrix(c):
    """y = c * x in F2[X]/(X^12-1): y_i = sum_j c_j x_{i-j}."""
    M = np.zeros((12, 12), dtype=np.int64)
    for i in range(12):
        for j in range(12):
            if c >> j & 1:
                M[i, (i - j) % 12] = 1
    return M


def mult_matrix(k):
    M = np.zeros((12, 12), dtype=np.int64)
    for i in range(12):
        M[(k * i) % 12, i] = 1
    return M


def rank2(M):
    M = M.copy() % 2; r = 0
    for c in range(M.shape[1]):
        p = np.nonzero(M[r:, c])[0]
        if len(p) == 0: continue
        p = p[0] + r; M[[r, p]] = M[[p, r]]
        for i in np.nonzero(M[:, c])[0]:
            if i != r: M[i] ^= M[r]
        r += 1
        if r == M.shape[0]: break
    return r


def apply_map(M):
    """index array y(x) = M x over F2^12 (bit i of x = coordinate i)."""
    bits = (XS[:, None] >> np.arange(12)) & 1                     # 4096 x 12
    yb = (bits @ M.T) % 2
    return (yb << np.arange(12)).sum(axis=1)


def image_polar(G, ymap):
    t = np.zeros(4096, dtype=np.uint8); t[XOF.reshape(-1)] = G.reshape(-1)
    t2 = t[ymap]                                                   # f'(x) = f(M x)
    G2 = t2[XOF]
    v = 0
    for kk, (i, j) in enumerate(PAIRS6):
        ei, ej = 1 << i, 1 << j
        col = G2[:, ei ^ ej] ^ G2[:, ei] ^ G2[:, ej] ^ G2[:, 0]
        for z in np.nonzero(col)[0]:
            v |= 1 << (64 * kk + int(z))
    return format(v, "x")


if __name__ == "__main__":
    from bitj import load_model
    from poisson3_lista import todos_subespacos3
    from cert_arvore import polar_data
    model = load_model(); Vs = todos_subespacos3()
    bent = open(sys.argv[1]).read().split()
    bent_set = set(bent)
    rng = random.Random(3)
    units = [c for c in range(1, 4096) if rank2(circ_matrix(c)) == 12]
    print("invertible circulants:", len(units), flush=True)
    gens = {"m5": mult_matrix(5), "m7": mult_matrix(7)}
    for c in rng.sample(units, 10):
        gens["c%x" % c] = circ_matrix(c)
    ymaps = {g: apply_map(M) for g, M in gens.items()}
    edges = {}; problems = []
    for hx in bent:
        T0, K = polar_data(hx, model, Vs)
        pts = [T0] + [T0 ^ np.bitwise_xor.reduce([K[j] for j in range(len(K)) if rng.random() < 0.5] or [np.zeros_like(T0)], axis=0) for _ in range(2)]
        edges[hx] = {}
        for g, ym in ymaps.items():
            imgs = {image_polar(G, ym) for G in pts}
            if len(imgs) != 1:
                problems.append((hx[:12], g, "depends on the function"))
            im = sorted(imgs)[0]
            if im not in bent_set:
                problems.append((hx[:12], g, "image not a bent polar"))
            edges[hx][g] = im
    # components
    adj = {h: set() for h in bent}
    for h, d in edges.items():
        for g, im in d.items():
            if im in adj:
                adj[h].add(im); adj[im].add(h)
    seen = set(); comps = []
    for h in bent:
        if h in seen: continue
        st = [h]; comp = set()
        while st:
            x = st.pop()
            if x in comp: continue
            comp.add(x); st += list(adj[x] - comp)
        seen |= comp; comps.append(sorted(comp))
    print("problems:", problems[:10], len(problems))
    print("orbits:", len(comps), "sizes:", sorted(len(c) for c in comps))
    out = sys.argv[sys.argv.index("--out") + 1] if "--out" in sys.argv else "simetria.json"
    json.dump({"units": len(units), "generators": list(gens), "orbits": comps, "problems": problems}, open(out, "w"))
